# T O D O S   O S   C H A M A D O S ABERTOS
def listarChamadosAbertos():
    try:
        result_table2 = DB.ExecuteDataTable("Select OCORRENCIA.NUMERO, OCORRENCIA.ASSUNTO, OCORRENCIA.SITUACAO, OCORRENCIA.DATA_HORA_SOL, OCORRENCIA.DATA_HORA_ULT_ATUA, PESSOA.NOME As RESPONSAVEL, OCORRENCIA.ID_CLASSE_SUB_PROC_INI As IDENTIFICADOR_PROCESSO, PESSOA.USUARIO_REDE, Coalesce(CPE_CSC.CSC_DGCO, CPE_CSC.NUMERO_DGCO, CPE_FINANCEIRO.DGCO_BB) As CSC_DGCO, OCORRENCIA.ID_OCORRENCIA, CLASSE_SUB_PROCESSO.SIGLA,FLOOR(SYSDATE - OCORRENCIA.DATA_HORA_SOL) || ' dias e ' || FLOOR(MOD((SYSDATE - OCORRENCIA.DATA_HORA_SOL) * 24, 24)) || ' horas' AS TEMPO_EM_ABERTO From OCORRENCIA Left Join ORDEM_SERVICO On OCORRENCIA.ID_OCORRENCIA = ORDEM_SERVICO.ID_OCORRENCIA Left Join CPE_FINANCEIRO On OCORRENCIA.ID_OCORRENCIA = CPE_FINANCEIRO.ID_OCORRENCIA Left Join CP_ORDEM_SERVICO On OCORRENCIA.ID_OCORRENCIA = CP_ORDEM_SERVICO.ID_OCORRENCIA Left Join PESSOA On PESSOA.ID_PESSOA = OCORRENCIA.ID_RESPONSAVEL Left Join CPE_CSC On OCORRENCIA.ID_OCORRENCIA = CPE_CSC.ID_OCORRENCIA Left Join CLASSE_SUB_PROCESSO On OCORRENCIA.ID_CLASSE_SUB_PROC_INI = CLASSE_SUB_PROCESSO.ID_CLASSE_SUB_PROCESSO Where OCORRENCIA.SITUACAO = 'Aberto' And (CLASSE_SUB_PROCESSO.SIGLA In ('ADT', 'ANGACOL', 'ANALISEPROJETOBASICO', 'ALTERARDADOSBANCARIOS', 'AVFOR', 'AVALIAFISCASERVICOOO', 'ROTINAAVALIACAO', 'AVSENCERRACONTRATO', 'DESIGNASISCCON2', 'DESIGNACAOSISCONNN', '423', 'DISTRATOERESCI', 'EMISSAOATESTADOFORNECEDOR', 'NOTIFICAFORNECEDORADITAMENTO2', 'ONBOARD', 'PROCESSADM', 'REVISAOOC', 'TERMOACEITEDESIGNACAOO', 'TERMOINTERVCONTRAT', 'ANAGARANCONT', 'AUTORIZARALTDADOSBANC', 'AVALIFORNECEDORES', 'AVISOENCERRACONT', 'DESIGNACAODEINTERVENIENTES', 'DISTRATOERESCISAO', 'ATESTADOCAPTECFORNECEDOR', 'NOTIFICACOESFORNECEDOR', 'ADITAMENTOSOL', 'TERMODEDESIGNACAO', 'ENCERRAMENTODECONTRATO', 'INSERIRDOCSGESCON') or OCORRENCIA.ID_CLASSE_SUB_PROC_INI In (600, 379, 395, 598, 380, 536, 357, 348, 625, 637, 654, 635, 641, 659, 658, 640, 655, 404, 327, 346))")
        
        json_data = JsonConvert.SerializeObject(result_table2)
        return json_data
    except Exception as e:  
        return "Erro ao executar a consulta: " + str(e)



# T O D O S   O S   C H A M A D O S
def listarChamados():
    try:
        result_table2 = DB.ExecuteDataTable("Select OCORRENCIA.NUMERO, OCORRENCIA.ASSUNTO, OCORRENCIA.SITUACAO, OCORRENCIA.DATA_HORA_SOL, OCORRENCIA.DATA_HORA_FIM_REAL As DATA_HORA_FIM_SOL, OCORRENCIA.DATA_HORA_ULT_ATUA, PESSOA.NOME As RESPONSAVEL, OCORRENCIA.ID_CLASSE_SUB_PROC_INI As IDENTIFICADOR_PROCESSO, PESSOA.USUARIO_REDE, Coalesce(CPE_CSC.CSC_DGCO, CPE_CSC.NUMERO_DGCO, CPE_FINANCEIRO.DGCO_BB) As CSC_DGCO, OCORRENCIA.ID_OCORRENCIA, CLASSE_SUB_PROCESSO.SIGLA, FLOOR(OCORRENCIA.DATA_HORA_FIM_REAL - OCORRENCIA.DATA_HORA_SOL) || ' dias e ' || FLOOR(MOD((OCORRENCIA.DATA_HORA_FIM_REAL - OCORRENCIA.DATA_HORA_SOL) * 24, 24)) || ' horas' AS TEMPO_TRATAMENTO From OCORRENCIA Left Join ORDEM_SERVICO On OCORRENCIA.ID_OCORRENCIA = ORDEM_SERVICO.ID_OCORRENCIA Left Join CPE_FINANCEIRO On OCORRENCIA.ID_OCORRENCIA = CPE_FINANCEIRO.ID_OCORRENCIA Left Join CP_ORDEM_SERVICO On OCORRENCIA.ID_OCORRENCIA = CP_ORDEM_SERVICO.ID_OCORRENCIA Left Join PESSOA On PESSOA.ID_PESSOA = OCORRENCIA.ID_RESPONSAVEL Left Join CPE_CSC On OCORRENCIA.ID_OCORRENCIA = CPE_CSC.ID_OCORRENCIA Left Join CLASSE_SUB_PROCESSO On OCORRENCIA.ID_CLASSE_SUB_PROC_INI = CLASSE_SUB_PROCESSO.ID_CLASSE_SUB_PROCESSO Where OCORRENCIA.SITUACAO != 'Aberto' And (CLASSE_SUB_PROCESSO.SIGLA In ('ADT', 'ANGACOL', 'ANALISEPROJETOBASICO', 'ALTERARDADOSBANCARIOS', 'AVSENCERRACONTRATO', '423', 'DISTRATOERESCI', 'EMISSAOATESTADOFORNECEDOR', 'NOTIFICAFORNECEDORADITAMENTO2', 'PROCESSADM', 'REVISAOOC', 'ANAGARANCONT', 'AUTORIZARALTDADOSBANC', 'AVISOENCERRACONT', 'DISTRATOERESCISAO', 'ATESTADOCAPTECFORNECEDOR', 'NOTIFICACOESFORNECEDOR', 'ADITAMENTOSOL', 'ENCERRAMENTODECONTRATO', 'INSERIRDOCSGESCON') or OCORRENCIA.ID_CLASSE_SUB_PROC_INI In (600, 379, 395, 598, 380, 536, 357, 348, 625, 659, 404, 327, 346))")
        
        json_data = JsonConvert.SerializeObject(result_table2)
        return json_data
    except Exception as e:
        return "Erro ao executar a consulta: " + str(e)





# S O L I C I T A Ç Õ E S   D E   N O T I F I C A Ç Ã O
def listarSolicitacoesNotificacao():
    try:
        result_table2 = DB.ExecuteDataTable("SELECT OCORRENCIA.NUMERO, OCORRENCIA.ASSUNTO, OCORRENCIA.SITUACAO, OCORRENCIA.DATA_HORA_ULT_ATUA, CLASSE_SUB_PROCESSO.ID_CLASSE_SUB_PROCESSO, OCORRENCIA.DATA_HORA_SOL, OCORRENCIA.DATA_HORA_FIM_REAL As DATA_HORA_FIM_SOL, CPE_CSC.OBJETO_CONTRATO, CPE_CSC.CSC_DATA_FIM, CPE_CSC.CSC_DGCO, CPE_CSC.OBSERVACAO, CP_ORDEM_SERVICO.NOME_FORNECEDOR, ORDEM_SERVICO.DESCRICAO_DETALHADA, PESSOA.NOME AS FISCAL_DE_SERVICO, PESSOA1.NOME AS FISCAL_ADM_DO_CONTRATO, PESSOA2.NOME AS GESTOR_DO_CONTRATO, OCORRENCIA.ID_OCORRENCIA, PESSOA3.NOME AS RESPONSAVEL, PESSOA3.USUARIO_REDE AS USUARIO_RESPONSAVEL, CLASSE_SUB_PROCESSO.SIGLA, CPE_CONTRATOS02.CLAUSULA_CONTRATUAL_DESCUMPRIDA, CASE WHEN OCORRENCIA.SITUACAO = 'Aberto' THEN FLOOR(SYSDATE - OCORRENCIA.DATA_HORA_SOL) || ' dias e ' || FLOOR(MOD((SYSDATE - OCORRENCIA.DATA_HORA_SOL) * 24, 24)) || ' horas' ELSE FLOOR(OCORRENCIA.DATA_HORA_FIM_REAL - OCORRENCIA.DATA_HORA_SOL) || ' dias e ' || FLOOR(MOD((OCORRENCIA.DATA_HORA_FIM_REAL - OCORRENCIA.DATA_HORA_SOL) * 24, 24)) || ' horas' END AS TEMPO,VERSAO_APROVACAO.VERSAO AS VERSAO_APROVACAO, APROVACAO.ID_ASSUNTO_APROVACAO, APROVACAO.SITUACAO AS SITUACAO_APROVACAO, VERSAO_APROVACAO.SITUACAO AS SITUACAO_VERSAO_APROVACAO, APROVACAO.MOTIVO AS MOTIVO_APROVACAO, VERSAO_APROVACAO.DATA_HORA_CRIACAO AS DATA_HORA_CRIACAO_VERSAO,PESSOA4.NOME AS APROVADOR FROM OCORRENCIA LEFT JOIN CLASSE_SUB_PROCESSO ON CLASSE_SUB_PROCESSO.ID_CLASSE_SUB_PROCESSO = OCORRENCIA.ID_CLASSE_SUB_PROC_INI LEFT JOIN CPE_CSC ON OCORRENCIA.ID_OCORRENCIA = CPE_CSC.ID_OCORRENCIA LEFT JOIN CP_ORDEM_SERVICO ON OCORRENCIA.ID_OCORRENCIA = CP_ORDEM_SERVICO.ID_OCORRENCIA LEFT JOIN ORDEM_SERVICO ON OCORRENCIA.ID_OCORRENCIA = ORDEM_SERVICO.ID_OCORRENCIA LEFT JOIN PESSOA ON PESSOA.ID_PESSOA = CPE_CSC.FISCAL_DE_SERVICO LEFT JOIN PESSOA PESSOA1 ON PESSOA1.ID_PESSOA = CPE_CSC.FISCAL_ADM_DO_CONTRATO LEFT JOIN PESSOA PESSOA2 ON PESSOA2.ID_PESSOA = CPE_CSC.GESTOR_DO_CONTRATO LEFT JOIN PESSOA PESSOA3 ON PESSOA3.ID_PESSOA = OCORRENCIA.ID_RESPONSAVEL LEFT JOIN CPE_CONTRATOS02 ON OCORRENCIA.ID_OCORRENCIA = CPE_CONTRATOS02.ID_OCORRENCIA LEFT JOIN ASSUNTO_APROVACAO ON OCORRENCIA.ID_OCORRENCIA = ASSUNTO_APROVACAO.ID_OCORRENCIA LEFT JOIN APROVACAO ON APROVACAO.ID_ASSUNTO_APROVACAO = ASSUNTO_APROVACAO.ID_ASSUNTO_APROVACAO LEFT JOIN VERSAO_APROVACAO ON VERSAO_APROVACAO.ID_ASSUNTO_APROVACAO = ASSUNTO_APROVACAO.ID_ASSUNTO_APROVACAO LEFT JOIN PESSOA PESSOA4 ON APROVACAO.ID_PESSOA = PESSOA4.ID_PESSOA WHERE (CLASSE_SUB_PROCESSO.ID_CLASSE_SUB_PROCESSO IN (600) OR CLASSE_SUB_PROCESSO.SIGLA IN ('NOTIFICAFORNECEDORADITAMENTO2', 'NOTIFICACOESFORNECEDOR'))")
        
        json_data = JsonConvert.SerializeObject(result_table2)
        return json_data
    except Exception as e:
        return "Erro ao executar a consulta: " + str(e)


