def listarRevisoesOrdensCompra():
    try:
        result_table2 = DB.ExecuteDataTable("WITH AA_ULTIMO AS (SELECT AA1.ID_OCORRENCIA, MAX(AA1.ID_ASSUNTO_APROVACAO) AS ID_ASSUNTO_APROVACAO FROM ASSUNTO_APROVACAO AA1 GROUP BY AA1.ID_OCORRENCIA), ULTIMO_APROVADOR AS (SELECT AAU.ID_OCORRENCIA, P.NOME AS APROVADOR FROM AA_ULTIMO AAU JOIN (SELECT A.ID_ASSUNTO_APROVACAO, A.ID_PESSOA, ROW_NUMBER() OVER (PARTITION BY A.ID_ASSUNTO_APROVACAO ORDER BY A.DATA_HORA_EVIDENCIA DESC) AS RN FROM APROVACAO A) A1 ON A1.ID_ASSUNTO_APROVACAO = AAU.ID_ASSUNTO_APROVACAO AND A1.RN = 1 JOIN PESSOA P ON P.ID_PESSOA = A1.ID_PESSOA) SELECT O.ASSUNTO, O.DATA_HORA_SOL, O.ID_CLASSE_SUB_PROC_INI, O.NUMERO, O.SITUACAO, O.DATA_HORA_ULT_ATUA, O.DATA_HORA_FIM_REAL AS DATA_HORA_FIM_SOL, O.ID_OCORRENCIA, OS.DESCRICAO_DETALHADA, CP.CNPJ, CP.NOME_FORNECEDOR, CP.NUMERO_OC, CSC.CSC_DGCO, CSC.NUMERO_RC, OS.JUSTIFICATIVA, CP.CPF, CSC.CSC_CPF, CSC.FISICA_JUDIRICA, CP.SIM_NAO, P.NOME AS RESPONSAVEL, P.USUARIO_REDE AS USUARIO_RESPONSAVEL, CSP.SIGLA, CASE WHEN O.SITUACAO = 'Aberto' THEN FLOOR(SYSDATE - O.DATA_HORA_SOL) || ' dias e ' || FLOOR(MOD((SYSDATE - O.DATA_HORA_SOL) * 24, 24)) || ' horas' ELSE FLOOR(O.DATA_HORA_FIM_REAL - O.DATA_HORA_SOL) || ' dias e ' || FLOOR(MOD((O.DATA_HORA_FIM_REAL - O.DATA_HORA_SOL) * 24, 24)) || ' horas' END AS TEMPO, UA.APROVADOR FROM OCORRENCIA O LEFT JOIN ORDEM_SERVICO OS ON O.ID_OCORRENCIA = OS.ID_OCORRENCIA LEFT JOIN CP_ORDEM_SERVICO CP ON OS.ID_OCORRENCIA = CP.ID_OCORRENCIA LEFT JOIN CPE_CSC CSC ON O.ID_OCORRENCIA = CSC.ID_OCORRENCIA LEFT JOIN PESSOA P ON P.ID_PESSOA = O.ID_RESPONSAVEL LEFT JOIN CLASSE_SUB_PROCESSO CSP ON O.ID_CLASSE_SUB_PROC_INI = CSP.ID_CLASSE_SUB_PROCESSO LEFT JOIN AA_ULTIMO AAU ON AAU.ID_OCORRENCIA = O.ID_OCORRENCIA LEFT JOIN ULTIMO_APROVADOR UA ON UA.ID_OCORRENCIA = O.ID_OCORRENCIA WHERE (O.ID_CLASSE_SUB_PROC_INI IN (395) OR CSP.SIGLA IN ('REVISAOOC'))")
        
        json_data = JsonConvert.SerializeObject(result_table2)
        return json_data
    except Exception as e:
        return "Erro ao executar a consulta: " + str(e)


