def buscarChamadosDesignacao():
    try:
        result_table2 = DB.ExecuteDataTable("WITH ULTIMO_AA AS (SELECT AA.ID_OCORRENCIA, AA.ID_ASSUNTO_APROVACAO, ROW_NUMBER() OVER (PARTITION BY AA.ID_OCORRENCIA ORDER BY AA.ID_ASSUNTO_APROVACAO DESC) AS RN FROM ASSUNTO_APROVACAO AA), ULTIMO_APROV AS (SELECT UA.ID_OCORRENCIA, A.ID_PESSOA, ROW_NUMBER() OVER (PARTITION BY UA.ID_OCORRENCIA ORDER BY A.DATA_HORA_EVIDENCIA DESC) AS RN FROM ULTIMO_AA UA JOIN APROVACAO A ON A.ID_ASSUNTO_APROVACAO = UA.ID_ASSUNTO_APROVACAO WHERE UA.RN = 1), APROVADOR_POR_OCORRENCIA AS (SELECT U.ID_OCORRENCIA, P2.NOME AS APROVADOR FROM ULTIMO_APROV U JOIN PESSOA P2 ON P2.ID_PESSOA = U.ID_PESSOA WHERE U.RN = 1), OS_AGR AS (SELECT ID_OCORRENCIA, MIN(NOME_FORNECEDOR) AS NOME_FORNECEDOR, MIN(OBJETO_CONTRATACAO) AS OBJETO_CONTRATACAO FROM CP_ORDEM_SERVICO GROUP BY ID_OCORRENCIA), FIN_AGR AS (SELECT ID_OCORRENCIA, MIN(DGCO_BB) AS DGCO_BB FROM CPE_FINANCEIRO GROUP BY ID_OCORRENCIA), CTRT_AGR AS (SELECT ID_OCORRENCIA, MIN(COMBOBOX_6) AS TIPO_DESIGNACAO FROM CPE_CONTRATOS GROUP BY ID_OCORRENCIA) SELECT O.ID_OCORRENCIA AS IDENTIFICADOR, O.ID_CLASSE_SUB_PROC_INI, O.DATA_HORA_ULT_ATUA, O.DATA_HORA_SOL, O.ASSUNTO, O.DATA_HORA_SOL, O.NUMERO, O.SITUACAO, OS.NOME_FORNECEDOR, O.DATA_HORA_FIM_REAL AS DATA_HORA_FIM_SOL, FIN.DGCO_BB AS DGCO, OS.OBJETO_CONTRATACAO, CTRT.TIPO_DESIGNACAO, CSP.SIGLA, P.NOME AS SOLICITANTE, P1.NOME AS RESPONSAVEL, (SELECT RTRIM(XMLAGG(XMLELEMENT(e, DGCO || '; ').EXTRACT('//text()') ORDER BY DGCO).GetClobVal(), '; ') FROM Z_00143_GRID_DESIGNACAO WHERE ID_OCORRENCIA = O.ID_OCORRENCIA) AS DGCO_LISTA, (SELECT RTRIM(XMLAGG(XMLELEMENT(e, SUBSTR(RAZAO_SOCIAL, 1, 59) || '; ').EXTRACT('//text()') ORDER BY RAZAO_SOCIAL).GetClobVal(), '; ') FROM Z_00143_GRID_DESIGNACAO WHERE ID_OCORRENCIA = O.ID_OCORRENCIA) AS RAZAO_SOCIAL_LISTA, CASE WHEN O.SITUACAO = 'Aberto' THEN FLOOR(SYSDATE - O.DATA_HORA_SOL) || ' dias e ' || FLOOR(MOD((SYSDATE - O.DATA_HORA_SOL) * 24, 24)) || ' horas' ELSE FLOOR(O.DATA_HORA_FIM_REAL - O.DATA_HORA_SOL) || ' dias e ' || FLOOR(MOD((O.DATA_HORA_FIM_REAL - O.DATA_HORA_SOL) * 24, 24)) || ' horas' END AS TEMPO, AP.APROVADOR FROM OCORRENCIA O LEFT JOIN OS_AGR OS ON OS.ID_OCORRENCIA = O.ID_OCORRENCIA LEFT JOIN FIN_AGR FIN ON FIN.ID_OCORRENCIA = O.ID_OCORRENCIA LEFT JOIN CTRT_AGR CTRT ON CTRT.ID_OCORRENCIA = O.ID_OCORRENCIA LEFT JOIN CLASSE_SUB_PROCESSO CSP ON O.ID_CLASSE_SUB_PROC_INI = CSP.ID_CLASSE_SUB_PROCESSO LEFT JOIN PESSOA P ON O.ID_CLIENTE = P.ID_PESSOA LEFT JOIN PESSOA P1 ON O.ID_RESPONSAVEL = P1.ID_PESSOA LEFT JOIN APROVADOR_POR_OCORRENCIA AP ON AP.ID_OCORRENCIA = O.ID_OCORRENCIA WHERE (O.ID_CLASSE_SUB_PROC_INI IN (654, 635)) OR (CSP.SIGLA IN ('DESIGNACAOSISCONNN', 'DESIGNASISCCON2', 'DESIGNACAODEINTERVENIENTES'))")
        
        json_data = JsonConvert.SerializeObject(result_table2)
        return json_data
    except Exception as e:
        return "Erro ao executar a consulta: " + str(e)


def buscarDetalhesDesignacao(numeroOs):
    try:
        result_table2 = DB.ExecuteDataTable("SELECT OCORRENCIA.ID_OCORRENCIA AS IDENTIFICADOR, OCORRENCIA.ID_CLASSE_SUB_PROC_INI, OCORRENCIA.DATA_HORA_ULT_ATUA, OCORRENCIA.DATA_HORA_SOL, OCORRENCIA.ASSUNTO, OCORRENCIA.DATA_HORA_SOL, OCORRENCIA.NUMERO, OCORRENCIA.SITUACAO, CP_ORDEM_SERVICO.NOME_FORNECEDOR, OCORRENCIA.DATA_HORA_FIM_REAL AS DATA_HORA_FIM_SOL, CPE_FINANCEIRO1.DGCO_BB AS DGCO, CP_ORDEM_SERVICO.OBJETO_CONTRATACAO, CPE_CONTRATOS.COMBOBOX_6 AS tipo_designacao, CLASSE_SUB_PROCESSO.SIGLA, PESSOA.NOME AS SOLICITANTE, PESSOA1.NOME AS RESPONSAVEL, LISTAGG(Z_00143_GRID_DESIGNACAO.DGCO, '; ') WITHIN GROUP (ORDER BY Z_00143_GRID_DESIGNACAO.DGCO) AS DGCO_LISTA, LISTAGG(SUBSTR(Z_00143_GRID_DESIGNACAO.RAZAO_SOCIAL, 1, 59), '; ') WITHIN GROUP (ORDER BY Z_00143_GRID_DESIGNACAO.RAZAO_SOCIAL) AS RAZAO_SOCIAL_LISTA, CASE WHEN OCORRENCIA.SITUACAO = 'Aberto' THEN FLOOR(SYSDATE - OCORRENCIA.DATA_HORA_SOL) || ' dias e ' || FLOOR(MOD((SYSDATE - OCORRENCIA.DATA_HORA_SOL) * 24, 24)) || ' horas' ELSE FLOOR(OCORRENCIA.DATA_HORA_FIM_REAL - OCORRENCIA.DATA_HORA_SOL) || ' dias e ' || FLOOR(MOD((OCORRENCIA.DATA_HORA_FIM_REAL - OCORRENCIA.DATA_HORA_SOL) * 24, 24)) || ' horas' END AS TEMPO, (SELECT versao FROM (SELECT VA.VERSAO AS versao FROM VERSAO_APROVACAO VA WHERE VA.ID_ASSUNTO_APROVACAO = ASSUNTO_APROVACAO.ID_ASSUNTO_APROVACAO ORDER BY VA.DATA_HORA_CRIACAO DESC) WHERE ROWNUM = 1) AS VERSAO_APROVACAO, ASSUNTO_APROVACAO.ID_ASSUNTO_APROVACAO, (SELECT situacao FROM (SELECT A.SITUACAO AS situacao FROM APROVACAO A WHERE A.ID_ASSUNTO_APROVACAO = ASSUNTO_APROVACAO.ID_ASSUNTO_APROVACAO ORDER BY A.DATA_HORA_EVIDENCIA DESC) WHERE ROWNUM = 1) AS SITUACAO_APROVACAO, (SELECT situacao FROM (SELECT VA.SITUACAO AS situacao FROM VERSAO_APROVACAO VA WHERE VA.ID_ASSUNTO_APROVACAO = ASSUNTO_APROVACAO.ID_ASSUNTO_APROVACAO ORDER BY VA.DATA_HORA_CRIACAO DESC) WHERE ROWNUM = 1) AS SITUACAO_VERSAO_APROVACAO, (SELECT motivo FROM (SELECT A.MOTIVO AS motivo FROM APROVACAO A WHERE A.ID_ASSUNTO_APROVACAO = ASSUNTO_APROVACAO.ID_ASSUNTO_APROVACAO ORDER BY A.DATA_HORA_EVIDENCIA DESC) WHERE ROWNUM = 1) AS MOTIVO_APROVACAO, (SELECT data_criacao FROM (SELECT VA.DATA_HORA_CRIACAO AS data_criacao FROM VERSAO_APROVACAO VA WHERE VA.ID_ASSUNTO_APROVACAO = ASSUNTO_APROVACAO.ID_ASSUNTO_APROVACAO ORDER BY VA.DATA_HORA_CRIACAO DESC) WHERE ROWNUM = 1) AS DATA_HORA_CRIACAO_VERSAO, (SELECT nome_aprovador FROM (SELECT P2.NOME AS nome_aprovador FROM APROVACAO A JOIN PESSOA P2 ON A.ID_PESSOA = P2.ID_PESSOA WHERE A.ID_ASSUNTO_APROVACAO = ASSUNTO_APROVACAO.ID_ASSUNTO_APROVACAO ORDER BY A.DATA_HORA_EVIDENCIA DESC) WHERE ROWNUM = 1) AS APROVADOR FROM OCORRENCIA LEFT JOIN CPE_FINANCEIRO ON OCORRENCIA.ID_OCORRENCIA = CPE_FINANCEIRO.ID_OCORRENCIA LEFT JOIN CP_ORDEM_SERVICO ON OCORRENCIA.ID_OCORRENCIA = CP_ORDEM_SERVICO.ID_OCORRENCIA LEFT JOIN CPE_FINANCEIRO CPE_FINANCEIRO1 ON OCORRENCIA.ID_OCORRENCIA = CPE_FINANCEIRO1.ID_OCORRENCIA LEFT JOIN CLASSE_SUB_PROCESSO ON OCORRENCIA.ID_CLASSE_SUB_PROC_INI = CLASSE_SUB_PROCESSO.ID_CLASSE_SUB_PROCESSO LEFT JOIN CPE_CONTRATOS ON OCORRENCIA.ID_OCORRENCIA = CPE_CONTRATOS.ID_OCORRENCIA LEFT JOIN PESSOA ON OCORRENCIA.ID_CLIENTE = PESSOA.ID_PESSOA LEFT JOIN PESSOA PESSOA1 ON OCORRENCIA.ID_RESPONSAVEL = PESSOA1.ID_PESSOA LEFT JOIN Z_00143_GRID_DESIGNACAO ON OCORRENCIA.ID_OCORRENCIA = Z_00143_GRID_DESIGNACAO.ID_OCORRENCIA LEFT JOIN ASSUNTO_APROVACAO ON OCORRENCIA.ID_OCORRENCIA = ASSUNTO_APROVACAO.ID_OCORRENCIA WHERE (OCORRENCIA.ID_CLASSE_SUB_PROC_INI IN (654, 635) OR CLASSE_SUB_PROCESSO.SIGLA IN ('DESIGNACAOSISCONNN', 'DESIGNASISCCON2', 'DESIGNACAODEINTERVENIENTES')) AND OCORRENCIA.NUMERO = '"+str(numeroOs)+"' GROUP BY OCORRENCIA.ID_OCORRENCIA, OCORRENCIA.ID_CLASSE_SUB_PROC_INI, OCORRENCIA.DATA_HORA_ULT_ATUA, OCORRENCIA.ASSUNTO, OCORRENCIA.DATA_HORA_SOL, OCORRENCIA.NUMERO, OCORRENCIA.SITUACAO, CP_ORDEM_SERVICO.NOME_FORNECEDOR, OCORRENCIA.DATA_HORA_FIM_REAL, CPE_FINANCEIRO1.DGCO_BB, CP_ORDEM_SERVICO.OBJETO_CONTRATACAO, CPE_CONTRATOS.COMBOBOX_6, CLASSE_SUB_PROCESSO.SIGLA, PESSOA.NOME, PESSOA1.NOME, ASSUNTO_APROVACAO.ID_ASSUNTO_APROVACAO")
        
        json_data = JsonConvert.SerializeObject(result_table2)
        return json_data
    except Exception as e:
        return "Erro ao executar a consulta: " + str(e)

        
