def listarInserirDocumentosContratuais():
    try:
        result_table2 = DB.ExecuteDataTable("Select OCORRENCIA.NUMERO As NUMERO, OCORRENCIA.SITUACAO As SITUACAO, OCORRENCIA.ASSUNTO As ASSUNTO, OCORRENCIA.DATA_HORA_SOL As DATA_HORA_SOL, OCORRENCIA.DATA_HORA_ULT_ATUA As DATA_HORA_ULT_ATUA, OCORRENCIA.DATA_HORA_FIM_REAL As DATA_HORA_FIM_SOL, PESSOA.NOME As RESPONSAVEL, PESSOA_CLIENTE.NOME As CLIENTE, CPE_FINANCEIRO.DGCO_BB As CSC_DGCO, CP_ORDEM_SERVICO.NOME_FORNECEDOR As NOME_FORNECEDOR, Case When OCORRENCIA.SITUACAO = 'Aberto' Then Floor(SysDate - OCORRENCIA.DATA_HORA_SOL) || ' dias e ' || Floor(Mod((SysDate - OCORRENCIA.DATA_HORA_SOL) * 24, 24)) || ' horas' Else Floor(OCORRENCIA.DATA_HORA_FIM_REAL - OCORRENCIA.DATA_HORA_SOL) || ' dias e ' || Floor(Mod((OCORRENCIA.DATA_HORA_FIM_REAL - OCORRENCIA.DATA_HORA_SOL) * 24, 24)) || ' horas' End As TEMPO, PESSOA_AREA_DEMANDANTE.NOME As RESPONSAVEL_AREA_DEMANDANTE, CP_ORDEM_SERVICO.SCR_TODOS_RH As AREA_CONTRATO, CPE_CSC.DIRETORIA_GERENCIA As DIRETORIA_GERENCIA, CPE_CSC.CSC_DATA_INICIO As INICIO_VIGENCIA, CPE_CSC.CSC_DATA_FIM As FIM_VIGENCIA, OCORRENCIA.ID_CLASSE_SUB_PROC_INI As IDENTIFICADOR, COALESCE(CAST(CPE_CSC.OBJETO_CONTRATO AS VARCHAR2(4000)), CAST(CPE_CSC.OBS21 AS VARCHAR2(4000)) ) AS OBJETO From OCORRENCIA Left Join CLASSE_SUB_PROCESSO On CLASSE_SUB_PROCESSO.ID_CLASSE_SUB_PROCESSO = OCORRENCIA.ID_CLASSE_SUB_PROC_INI Left Join ORDEM_SERVICO On ORDEM_SERVICO.ID_OCORRENCIA = OCORRENCIA.ID_OCORRENCIA Left Join PESSOA On OCORRENCIA.ID_RESPONSAVEL = PESSOA.ID_PESSOA Left Join PESSOA PESSOA_CLIENTE On OCORRENCIA.ID_CLIENTE = PESSOA_CLIENTE.ID_PESSOA Left Join CPE_FINANCEIRO On OCORRENCIA.ID_OCORRENCIA = CPE_FINANCEIRO.ID_OCORRENCIA Left Join CP_ORDEM_SERVICO On OCORRENCIA.ID_OCORRENCIA = CP_ORDEM_SERVICO.ID_OCORRENCIA Left Join PESSOA PESSOA_AREA_DEMANDANTE On CP_ORDEM_SERVICO.FAVORECIDO_TODOS = PESSOA_AREA_DEMANDANTE.ID_PESSOA Left Join CPE_CSC On OCORRENCIA.ID_OCORRENCIA = CPE_CSC.ID_OCORRENCIA Where (CLASSE_SUB_PROCESSO.ID_CLASSE_SUB_PROCESSO In (346)) Or (CLASSE_SUB_PROCESSO.SIGLA In ('INSERIRDOCSGESCON')) Order By OCORRENCIA.DATA_HORA_SOL")
        
        json_data = JsonConvert.SerializeObject(result_table2)
        return json_data
    except Exception as e:
        return "Erro ao executar a consulta: " + str(e)


