def enviaDadosDue():
    try:
        result_table2 = DB.ExecuteDataTable("Select CP_ORDEM_SERVICO.CNPJ As CNPJ, CP_ORDEM_SERVICO.SIM_NAO As NECESSARIO_BCK_CHECK, CP_ORDEM_SERVICO.ACAO_TOMADA As JUSTIFICATIVA, OCORRENCIA.ASSUNTO As ASSUNTO, CP_ORDEM_SERVICO.NOME_FORNECEDOR As RAZAO_SOCIAL, CPE_CONTRATOS.OBS5 As INFO_COMPLEMENTARES, CPE_CSC.CSC_VALOR1_A As VALOR_ARREMATADO, CPE_CSC.DIRETORIA_GERENCIA As DIRETORIA_GERENCIA, CPE_CONTRATOS.DIVISAO_DUEDILIGENCE As AREA, CPE_CSC.FUNDAMENTACAO As FUDAMENTACAO, CPE_CONTRATOS.MODALIDADE_DE_CONTRATACAO As MODALIDADE_CONTRAT, CPE_CSC.NUMERO_DGCO As DGCO, CPE_FINANCEIRO.OBJETO_QUALIF As OBJ_RESUMIDO, CPE_DESLOCAMENTO.VALOR_DESPESAS As SOMATORIO_CONTRATACAO, CPE_FINANCEIRO.VALOR_QUALIF As VALOR_CONTRATACAO, CPE_CSC.OBS6 As AJUSTES_NECESSARIOS, CPE_CSC.DATA_HORA_FIM As DATA_ANALISE, CPE_CONTRATOS.GRAUDERISCO_DUEDILIGENCE As GRAU_DE_RISCO, CPE_CSC.OBS21 As ANALISE_DISUP, CPE_CSC.SIM_NAO1 As GRANDE_EXPOSICAOBBTS, OCORRENCIA.ID_CLASSE_SUB_PROC As ID_OCORRENCIA, CPE_DESLOCAMENTO.VALOR_PASSAGEM As VALOR_ADITIVO1, OCORRENCIA.NUMERO, OCORRENCIA.DATA_HORA_CRIACAO, OCORRENCIA.SITUACAO, OCORRENCIA.ID_OCORRENCIA, OCORRENCIA.DATA_HORA_SOL, PESSOA.NOME, PESSOA1.NOME As GESTOR_DEMANDANTE, PESSOA2.NOME As RESPONSAVEL_AREA_CLIENTE From CP_ORDEM_SERVICO Left Join OCORRENCIA On OCORRENCIA.ID_OCORRENCIA = CP_ORDEM_SERVICO.ID_OCORRENCIA Left Join CPE_CONTRATOS On CP_ORDEM_SERVICO.ID_OCORRENCIA = CPE_CONTRATOS.ID_OCORRENCIA Left Join CPE_CSC On CPE_CONTRATOS.ID_OCORRENCIA = CPE_CSC.ID_OCORRENCIA Left Join CPE_FINANCEIRO On CPE_CSC.ID_OCORRENCIA = CPE_FINANCEIRO.ID_OCORRENCIA Left Join CPE_DESLOCAMENTO On CPE_FINANCEIRO.ID_OCORRENCIA = CPE_DESLOCAMENTO.ID_OCORRENCIA Left Join PESSOA On PESSOA.ID_PESSOA = OCORRENCIA.ID_RESPONSAVEL Left Join PESSOA PESSOA1 On PESSOA1.ID_PESSOA = CPE_CSC.TE_NOME_EMPREGADO Left Join PESSOA PESSOA2 On CP_ORDEM_SERVICO.FAVORECIDO_COBRA = PESSOA2.ID_PESSOA Where OCORRENCIA.ID_CLASSE_SUB_PROC = 534 Order By OCORRENCIA.NUMERO")

        
        json_data = JsonConvert.SerializeObject(result_table2)
        return json_data
    except Exception as e:
        return "Erro ao executar a consulta: " + str(e)


def enviaDadosCad():
    try:
        # ExecuteReader retorna um conjunto de resultados
        result_table2 = DB.ExecuteDataTable("Select F.status_matricula As STATUS_MATRICULA, F.nome As NOME, F.matricula As MATRICULA, F.gestor_posicao As GESTOR_POSICAO, F.cargo_funcional As CARGO_FUNCIONAL, F.CARGO,  F.funcao_gratificada As FUNCAO_GRATIFICADA,F.supervisor As SUPERVISOR, F.organizacao As ORGANIZACAO, F.unidade_negocio As UNIDADE_NEGOCIO, F.local_cidade As LOCAL_CIDADE,F.local_estado As LOCAL_ESTADO, F.numero_subcr_nivel1 As UOR_DIVISAO, F.descricao_subcr_nivel1 As DESCRICAO_DIVISAO, F.numero_subcr_nivel2 As UOR_GERENCIA,F.descricao_subcr_nivel2 As DESCRICAO_GERENCIA, F.numero_subcr_nivel3 As UOR_DIRETORIA, F.descricao_subcr_nivel3 As DESCRICAO_DIRETORIA, cp.DATA_NASCIMENTO As NASCIMENTO, cp.DATA_DE_ADMISSAO As ADMISSAO, P.EMAIL As EMAIL, P.USUARIO_REDE As USUARIO, P.BLOQUEADO As BLOQUEADO, c.scr_sigla As SIGLA_DIVISAO, c2.scr_sigla As SIGLA_GERENCIA, c3.scr_sigla As SIGLA_DIRETORIA From CAD_FUNCIONARIO_V F Inner Join cp_pessoa cp On F.matricula = cp.matricula Inner Join PESSOA P On cp.ID_PESSOA = P.id_pessoa Inner Join cob_gl_centro c On c.scr = F.numero_subcr_nivel1 Inner Join cob_gl_centro c2 On c2.scr = F.numero_subcr_nivel2 Inner Join cob_gl_centro c3 On c3.scr = F.numero_subcr_nivel3 Where f.CARGO_FUNCIONAL not in ('PRESTADOR DE SERVICO') And f.CARGO_FUNCIONAL IS NOT NULL Order By f.nome")
        
        
            
        
        json_data = JsonConvert.SerializeObject(result_table2)
        return json_data

    # Serializar a lista de pessoas para JSON
    except Exception as e:
        return "Erro ao executar a consulta: " + str(e)
        
        
        
