def listarChamadosAditamentosGeral():
    try:
        result_table2 = DB.ExecuteDataTable("SELECT CPE_FINANCEIRO.DGCO_BB AS DGCO, OCORRENCIA.ASSUNTO, OCORRENCIA.DATA_HORA_SOL AS DATA_HORA_SOLICITACAO, OCORRENCIA.DATA_HORA_FIM_REAL AS DATA_HORA_FIM_SOL, OCORRENCIA.DATA_HORA_ULT_ATUA, PESSOA.NOME AS SOLICITANTE, PESSOA1.NOME AS CONDUTOR, OCORRENCIA.SITUACAO, Z_00143_ADIT_SOL.LIST_AD AS LIST_AD, OCORRENCIA.NUMERO, CLASSE_SUB_PROCESSO.SIGLA, CLASSE_SUB_PROCESSO.ID_CLASSE_SUB_PROCESSO, CASE WHEN OCORRENCIA.SITUACAO = 'Aberto' THEN FLOOR(SYSDATE - OCORRENCIA.DATA_HORA_SOL) || ' dias e ' || FLOOR(MOD((SYSDATE - OCORRENCIA.DATA_HORA_SOL) * 24, 24)) || ' horas' ELSE FLOOR(OCORRENCIA.DATA_HORA_FIM_REAL - OCORRENCIA.DATA_HORA_SOL) || ' dias e ' || FLOOR(MOD((OCORRENCIA.DATA_HORA_FIM_REAL - OCORRENCIA.DATA_HORA_SOL) * 24, 24)) || ' horas' END AS TEMPO FROM OCORRENCIA LEFT JOIN CPE_FINANCEIRO ON OCORRENCIA.ID_OCORRENCIA = CPE_FINANCEIRO.ID_OCORRENCIA LEFT JOIN PESSOA ON OCORRENCIA.ID_CLIENTE = PESSOA.ID_PESSOA LEFT JOIN PESSOA PESSOA1 ON OCORRENCIA.ID_RESPONSAVEL = PESSOA1.ID_PESSOA LEFT JOIN Z_00143_ADIT_SOL ON OCORRENCIA.ID_OCORRENCIA = Z_00143_ADIT_SOL.ID_OCORRENCIA LEFT JOIN CLASSE_SUB_PROCESSO ON OCORRENCIA.ID_CLASSE_SUB_PROC_INI = CLASSE_SUB_PROCESSO.ID_CLASSE_SUB_PROCESSO WHERE CPE_FINANCEIRO.DGCO_BB IS NOT NULL AND (OCORRENCIA.ID_CLASSE_SUB_PROC_INI IN (379) OR CLASSE_SUB_PROCESSO.SIGLA IN ('ADT', 'ADITAMENTOSOL'))")
        
        json_data = JsonConvert.SerializeObject(result_table2)
        return json_data
    except Exception as e:
        return "Erro ao executar a consulta: " + str(e)




def realizarReservaDgco(fisica_juridica, cpf_cnpj, razao_social, descricao, matricula_solicitante, objeto):
    try:
        matriculaFiscalServ = matricula_solicitante
        id = 0
        colaboradores4 = DB.ExecuteDataTable("Select PESSOA.ID_PESSOA, PESSOA.NOME, CP_PESSOA.MATRICULA From PESSOA Inner Join CP_PESSOA On PESSOA.ID_PESSOA = CP_PESSOA.ID_PESSOA Where CP_PESSOA.MATRICULA = '" + matriculaFiscalServ.ToString()+"'")
 
        
        for row in colaboradores4.Rows:
            id = row["ID_PESSOA"]
        
        # Corrigido o argumento do assunto
        novaOS = OrdemServico.Nova(OrdemServico.Carrega('Numero', 589), "SOLICITRESERVDG", "RESERVDGCO", "Solicitação de Reserva DGCO - Dilic", Servico.Carrega(998), Pessoa.Carrega(id), Pessoa.Carrega(26709))
        
        novaOS.SetCustom('COMBOBOX1', 'Fornecedor')
        novaOS.DescricaoDetalhada = descricao
        
        novaOS.SetCustom('RAZAO_SOCIAL_CLIENTE', razao_social)
        novaOS.SetCustom('OBJETO_CONTRATACAO', objeto.ToString())
        
        if fisica_juridica == 'fisica':
            novaOS.SetCustom('CSC_CPF', cpf_cnpj)
            novaOS.ModificaCampoFormularioVisivel('CSC_CPF', True)
            novaOS.ModificaCampoFormularioVisivel('CNPJ', False)
            novaOS.SetCustom('JURIDICA_FISICA', 'Pessoa Física')
        else:
            novaOS.SetCustom('CNPJ', cpf_cnpj)
            novaOS.ModificaCampoFormularioVisivel('CNPJ', True)
            novaOS.ModificaCampoFormularioVisivel('CSC_CPF', False)
            novaOS.SetCustom('JURIDICA_FISICA', 'Pessoa Jurídica')
        
        
        novaOS.Salva()
        novaOS.AvancaAtividade()
        # Serializando o tipo de novaOS
        json_data = JsonConvert.SerializeObject([str(novaOS.Numero)])
        return json_data

    except Exception as e:
        return e.ToString()
        
        
