def atualizarAtividade(comando, os):
    try:
        

        lista = Utils.ExecuteDataTable("Select OCORRENCIA.ID_OCORRENCIA, ORDEM_SERVICO.ID_OCORRENCIA, OCORRENCIA.NUMERO From OCORRENCIA Inner Join ORDEM_SERVICO On ORDEM_SERVICO.ID_OCORRENCIA = OCORRENCIA.ID_OCORRENCIA Where OCORRENCIA.NUMERO ='" + os + "'")

        idOcorrencia = 0
        for linha in lista.Rows:
            idOcorrencia = linha["ID_OCORRENCIA"]
               
        chamado = OrdemServico.Carrega(Convert.ToInt32(idOcorrencia))


        if comando == "Avanca":
            chamado.AvancaAtividade()
        elif situacao == "Voltar":
            chamado.VoltaAtividade()
        else:
            raise Exception("Situação inválida.")

        chamado.Salva()
        
        
        return JsonConvert.SerializeObject(True)
    except Exception as e:
        return "Erro ao executar a consulta: " + str(e)
        
        
        

        
        
        
def apiPrimeiraDesignacao(dgco, razao_social, obj, comissao, matricula_gestor, uorGestor):
    try:
        

        idGestor = 0
        nomeGestor = ''
        uorId = 0
        gestor = DB.ExecuteDataTable("Select PESSOA.ID_PESSOA, PESSOA.NOME, CP_PESSOA.MATRICULA From PESSOA Inner Join CP_PESSOA On PESSOA.ID_PESSOA = CP_PESSOA.ID_PESSOA Where CP_PESSOA.MATRICULA = '" + matricula_gestor.ToString()+"'")
        
        for row in gestor.Rows:
            idGestor = row["ID_PESSOA"]
            nomeGestor = row["NOME"]
            
            
            
        uor = DB.ExecuteDataTable("Select ORGAO.ID_ORGAO, ORGAO.SIGLA, ORGAO.DESCRICAO, ORGAO.ID_GESTOR, ORGAO.ATIVO From ORGAO Where ORGAO.SIGLA = '" + uorGestor.ToString()+"'")
        
        for row in uor.Rows:
            uorId = row["DESCRICAO"]

        
        
        # Corrigido o argumento do assunto
        novaOS = OrdemServico.Nova(OrdemServico.Carrega('Numero', 654), "DESIGNACAODEINTERVENIENTES", "APIDESIGNACAOSUPRAVIZIO", "Designação de Intervenientes", Servico.Carrega(1482), Pessoa.Carrega(idGestor), Pessoa.Carrega(idGestor))
        
        
        

        
        novaOS.SetCustom('DGCO_BB', str(dgco))
        novaOS.SetCustom('NOME_FORNECEDOR', razao_social.ToString())
        novaOS.SetCustom('OBJETO_CONTRATACAO', obj.ToString())
        novaOS.SetCustom('SIM_NAO3', comissao.ToString())
        novaOS.SetCustom('FAVORECIDO_GESTOR', str(nomeGestor))
        novaOS.SetCustom('MATRICULA_GESTOR_TITULAR', str(matricula_gestor))
        
        novaOS.SetCustom('SCR_TODOS_RH', uorId.ToString())
        
        novaOS.DescricaoDetalhada = 'Designação Inicial de Fiscais de Serviço e Gestor Suplente!'
        
        
        

        novaOS.Salva()
        novaOS.AvancaAtividade()
        
        # Serializando o tipo de novaOS
        json_data = JsonConvert.SerializeObject([str(novaOS.Numero)])
        return json_data

    except Exception as e:
        return e.ToString()
        

    
    

def apiPrimeiraDesignacaoAdministrativo(dgco, razao_social, obj):
    try:
        
        idGestorCsc = 0
        nomeGestorCsc = ''
        matriculaGestorCsc = 0
        emailGerenteCsc = ''
        
        tableCsc = DB.ExecuteDataTable("Select ID_GESTOR From ORGAO WHERE ORGAO.SIGLA = '3000003341'")
        for row2 in tableCsc.Rows:
            idGestorCsc = row2['ID_GESTOR']
            

            
        gestorCsc = DB.ExecuteDataTable("Select PESSOA.ID_PESSOA, PESSOA.EMAIL, PESSOA.NOME, CP_PESSOA.MATRICULA From PESSOA Inner Join CP_PESSOA On PESSOA.ID_PESSOA = CP_PESSOA.ID_PESSOA Where CP_PESSOA.ID_PESSOA = '" + idGestorCsc.ToString()+"'")

        for row in gestorCsc.Rows:
            matriculaGestorCsc = row["MATRICULA"]
            nomeGestorCsc = row["NOME"]
            emailGerenteCsc = str(row['EMAIL'])
            

        
        
            
        
        #Corrigido o argumento do assunto
        novaOS = OrdemServico.Nova(OrdemServico.Carrega('Numero', 654), "DESIGNACAODEINTERVENIENTES", "APIDESIGNACAOSUPRAVIZIO2", "Designação de Intervenientes", Servico.Carrega(1482), Pessoa.Carrega(idGestorCsc), Pessoa.Carrega(idGestorCsc))
        
        
        
        
        
        novaOS.SetCustom('DGCO_BB', str(dgco))
        novaOS.SetCustom('NOME_FORNECEDOR', razao_social.ToString())
        novaOS.SetCustom('OBS21', obj.ToString())
        novaOS.SetCustom('FAVORECIDO_GESTOR', str(nomeGestorCsc))
        novaOS.SetCustom('MATRICULA_GESTOR_TITULAR', str(matriculaGestorCsc))
        
        
        novaOS.DescricaoDetalhada = 'Designação Inicial de Fiscais Administrativos!'
        

        novaOS.Salva()
        novaOS.AvancaAtividade()
        
        # Serializando o tipo de novaOS
        
        json_data = JsonConvert.SerializeObject([
            {
                "numero_os": str(novaOS.Numero),
                "nome_gestor": nomeGestorCsc,
                "email_gestor": emailGerenteCsc
            }
        ])
        return json_data


    except Exception as e:
        return e.ToString()
